SELECT CASE WHEN s.country IN ('UK', 'JP') THEN 'priority' ELSE 'other' END AS country_group, s.customer_id, SORT_ARRAY(COLLECT_SET(we.event_type)) AS event_type_list, MAX(we.event_time) AS last_event_time FROM web_events we INNER JOIN sessions s ON we.session_id = s.id GROUP BY CASE WHEN s.country IN ('UK', 'JP') THEN 'priority' ELSE 'other' END, s.customer_id ORDER BY last_event_time
